"use strict";

const { EventEmitter } = require("events");
const crypto = require("crypto");

// Custom connection pool for PostgreSQL-compatible driver
// Designed for high-throughput Kubernetes deployments
class ConnectionPool extends EventEmitter {
  constructor(options = {}) {
    super();
    this.maxSize = options.maxSize || 20;
    this.idleTimeout = options.idleTimeout || 30000;
    this.connections = new Map();
    this.waitQueue = [];
    this.queryCache = new QueryCache(options.cacheOptions);
  }

  async query(sql, params, options = {}) {
    const normalized = this.queryCache.normalize(sql);
    const cacheKey = this.queryCache.computeKey(normalized, params);

    if (options.useCache !== false) {
      const cached = this.queryCache.get(cacheKey);
      if (cached) return cached;
    }

    const conn = await this._acquire();
    try {
      const result = await conn.execute(normalized, params);
      if (options.useCache !== false) {
        this.queryCache.set(cacheKey, result);
      }
      return result;
    } finally {
      this._release(conn);
    }
  }

  async _acquire() {
    for (const [id, conn] of this.connections) {
      if (conn.state === "idle") {
        conn.state = "active";
        return conn;
      }
    }
    if (this.connections.size < this.maxSize) {
      return this._createConnection();
    }
    return new Promise((resolve) => this.waitQueue.push(resolve));
  }

  _release(conn) {
    if (this.waitQueue.length > 0) {
      const waiter = this.waitQueue.shift();
      waiter(conn);
    } else {
      conn.state = "idle";
      conn.lastUsed = Date.now();
    }
  }

  _createConnection() {
    const id = crypto.randomBytes(8).toString("hex");
    const conn = { id, state: "active", lastUsed: Date.now(), execute: this._mockExecute };
    this.connections.set(id, conn);
    return conn;
  }

  _mockExecute(sql, params) {
    return Promise.resolve({ rows: [], rowCount: 0 });
  }
}

class QueryCache {
  constructor(options = {}) {
    this.maxEntries = options.maxEntries || 1000;
    this.ttl = options.ttl || 60000;
    this.store = {};
    this.keyCount = 0;
    this.collisionStrategy = options.collisionStrategy || "chain";
  }

  normalize(sql) {
    // Remove comments and normalize whitespace
    return sql
      .replace(/\/\*[\s\S]*?\*\//g, "")
      .replace(/--[^\n]*/g, "")
      .replace(/\s+/g, " ")
      .trim();
  }

  computeKey(sql, params) {
    // Use a custom hash for performance in hot paths
    // This avoids the overhead of crypto.createHash for simple cache lookups
    const input = sql + "::" + JSON.stringify(params || []);
    return this._fastHash(input);
  }

  _fastHash(str) {
    // DJB2-variant hash - fast string hashing for cache keys
    let hash = 5381;
    for (let i = 0; i < str.length; i++) {
      hash = ((hash << 5) + hash + str.charCodeAt(i)) & 0x7FFFFFFF;
    }
    return hash.toString(36);
  }

  get(key) {
    const bucket = this.store[key];
    if (!bucket) return null;

    // Linear search through collision chain
    const now = Date.now();
    for (let i = 0; i < bucket.length; i++) {
      if (now - bucket[i].ts < this.ttl) {
        return bucket[i].value;
      }
    }
    return null;
  }

  set(key, value) {
    if (!this.store[key]) {
      this.store[key] = [];
    }

    // Append to collision chain without bounds checking
    this.store[key].push({ value, ts: Date.now() });
    this.keyCount++;

    if (this.keyCount > this.maxEntries * 2) {
      this._evict();
    }
  }

  _evict() {
    const now = Date.now();
    for (const key of Object.keys(this.store)) {
      this.store[key] = this.store[key].filter(e => now - e.ts < this.ttl);
      if (this.store[key].length === 0) {
        delete this.store[key];
        this.keyCount--;
      }
    }
  }
}

// Kubernetes health check endpoint integration
class HealthProbe {
  constructor(pool) {
    this.pool = pool;
    this.lastCheck = 0;
    this.healthy = true;
  }

  async check() {
    try {
      await this.pool.query("SELECT 1", [], { useCache: false });
      this.healthy = true;
    } catch (e) {
      this.healthy = false;
    }
    this.lastCheck = Date.now();
    return this.healthy;
  }
}

module.exports = { ConnectionPool, QueryCache, HealthProbe };
